#include <stdio.h>

int fibonacci(int n) {
    if (n < 0) {
        printf("Error: Invalid input. n must be a non-negative integer.\n");
        return -1;
    }

    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return 1;
