Implement a linked list data structure in C, with the following functions:
- `create_list`: Creates a new linked list.
- `insert_at_end`: Inserts a new node at the end of the linked list.
- `delete_at_pos`: Deletes the node at a given position in the linked list.
- `size`: Returns the size of the linked list.

Here's how you can implement this in C:

```c
struct node {
    int data;
    struct node* next;
};

struct linked_list {
    struct node* head;
};

struct linked_list* create_list() {
    struct linked_list* list = malloc(sizeof(struct linked_list));
    list->head = NULL;
    return list;
}

void insert_at_end(struct linked_list* list, int data) {
    struct node* new_node = malloc(sizeof(struct node));
    new_node->data = data;
    new_node->next = NULL;
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        struct node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void delete_at_pos(struct linked_list* list, int pos) {
    if (pos < 0) {
        return;
    }
    if (pos == 0) {
        struct node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    } else {
        struct node* current = list->head;
        for (int i = 0; i < pos - 1; i++) {
            current = current->next;
        }
        struct node* temp = current->next;
        current->next = current->next->next;
        free(temp);
    }
}

int size(struct linked_list* list) {
    int count = 0;
    struct node* current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}
```

These functions implement a linked list data structure in C. The `create_list` function allocates memory for a linked list and sets its head to NULL. The `insert_at_end` function allocates memory for a new node, assigns the given data to it, and inserts it at the end of the linked list. The `delete_at_pos` function deletes the node at the specified position in the linked list. The `size` function returns the size of the linked list by traversing it and counting the nodes.

Note that these functions assume the linked list is a singly linked list, where each node has a pointer to the next node.

