/**
 * free_list - function that
 * frees a list_t list.
 * @head: pointer to the head of the list
 * Return: void
 */void free_list(hash_node_t *head)
{
	hash_node_t *temp;

	temp = head;
	while (head)
	{

		temp = head;
		head = head->next;
		/*freeing the content*/
		if (temp->key)
			free(temp->key);
		if (temp->value)
			free(temp->value);
		free(temp);
	}
}

